+    }
+
+    @NotNull
+    public static SQLCompletionRequest create(
+        @NotNull SQLCompletionContext context,
+        @NotNull IDocument document,
+        int documentOffset,
+        boolean simpleMode
+    ) {
+        SQLParserContext parserContext = new SQLParserContext(
+            context.getDataSource(),
