+        @NotNull SQLCompletionContext context,
+        @NotNull IDocument document,
+        int documentOffset,
+        @Nullable SQLScriptElement activeQuery,
+        boolean simpleMode
+    ) {
+        return new SQLCompletionRequest(context, document, documentOffset, activeQuery, simpleMode);
+    }
+}
